1	package com.loja.checkout.dominio;
2	
3	import com.loja.checkout.dominio.clube.NivelClube;
4	import com.loja.checkout.dominio.cupom.ContextoCupom;
5	import com.loja.checkout.dominio.cupom.Cupom;
6	import com.loja.checkout.dominio.cupom.SemCupom;
7	import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
8	import com.loja.checkout.dominio.pagamento.FormaPagamento;
9	import com.loja.checkout.dominio.pagamento.ResultadoPagamento;
10	import org.springframework.stereotype.Service;
11	
12	import java.math.BigDecimal;
13	import java.util.List;
14	import java.util.Objects;
15	import java.util.Optional;
16	
17	/**
18	 * Calcula o resumo da compra. Esta classe só conhece a ordem do cálculo e a ordem das
19	 * conferências: quanto custa o frete, quanto desconta o cupom, quanto ajusta o pagamento
20	 * e o que o clube dá é responsabilidade de cada caso.
21	 */
22	@Service
23	public class CalculadoraResumo {
24	
25	    private static final int PARCELA_UNICA = 1;
26	
27	    private final Catalogo<ModalidadeEntrega> modalidades;
28	    private final Catalogo<Cupom> cupons;
29	    private final Catalogo<FormaPagamento> formasPagamento;
30	
31	    public CalculadoraResumo(List<ModalidadeEntrega> modalidades,
32	                             List<Cupom> cupons,
33	                             List<FormaPagamento> formasPagamento) {
34	        this.modalidades = new Catalogo<>(modalidades);
35	        this.cupons = new Catalogo<>(cupons);
36	        this.formasPagamento = new Catalogo<>(formasPagamento);
37	    }
38	
39	    public ResumoCompra calcular(PedidoInformado pedido) {
40	        Carrinho carrinho = carrinhoDe(pedido.itens());
41	        NivelClube nivel = NivelClube.buscar(pedido.nivelClube())
42	                .orElseThrow(() -> recusar(ErroCheckout.NIVEL_CLUBE_INVALIDO));
43	        Regiao regiao = Regiao.buscar(pedido.regiao())
44	                .orElseThrow(() -> recusar(ErroCheckout.REGIAO_INVALIDA));
45	
46	        ModalidadeEntrega modalidade = modalidades.buscar(pedido.modalidadeEntrega())
47	                .orElseThrow(() -> recusar(ErroCheckout.MODALIDADE_INVALIDA));
48	        BigDecimal pesoKg = carrinho.pesoKg();
49	        exigir(modalidade.atende(pesoKg), ErroCheckout.MODALIDADE_INDISPONIVEL);
50	
51	        BigDecimal subtotalProdutos = carrinho.subtotal();
52	        BigDecimal frete = nivel.freteCobrado(modalidade.frete(pesoKg));
53	
54	        Cupom cupom = cupomDe(pedido.cupom());
55	        ContextoCupom contexto = new ContextoCupom(carrinho, frete);
56	        exigir(cupom.aplicavel(contexto), ErroCheckout.CUPOM_NAO_APLICAVEL);
57	        BigDecimal descontoCupom = cupom.desconto(contexto);
58	
59	        FormaPagamento formaPagamento = formasPagamento.buscar(pedido.formaPagamento())
60	                .orElseThrow(() -> recusar(ErroCheckout.FORMA_PAGAMENTO_INVALIDA));
61	        int parcelas = Objects.requireNonNullElse(pedido.parcelas(), PARCELA_UNICA);
62	        exigir(formaPagamento.parcelasPermitidas(parcelas), ErroCheckout.PARCELAMENTO_INVALIDO);
63	
64	        BigDecimal seguro = regiao.seguro(subtotalProdutos);
65	        BigDecimal totalPedido = Dinheiro.arredonda(
66	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
67	        exigir(formaPagamento.atende(totalPedido), ErroCheckout.FORMA_PAGAMENTO_INDISPONIVEL);
68	
69	        ResultadoPagamento pagamento = formaPagamento.calcular(totalPedido, parcelas);
70	        BigDecimal totalFinal = Dinheiro.arredonda(pagamento.totalFinal());
71	
72	        return new ResumoCompra(
73	                subtotalProdutos,
74	                descontoCupom,
75	                Dinheiro.arredonda(frete),
76	                modalidade.prazoDias(),
77	                seguro,
78	                Dinheiro.arredonda(totalFinal.subtract(totalPedido)),
79	                totalFinal,
80	                parcelas,
81	                Dinheiro.arredonda(pagamento.valorParcela()),
82	                nivel.credito(subtotalProdutos),
83	                nivel.temBrinde(subtotalProdutos));
84	    }
85	
86	    private Carrinho carrinhoDe(List<ItemInformado> itens) {
87	        exigir(itens != null && !itens.isEmpty(), ErroCheckout.PEDIDO_INVALIDO);
88	        return new Carrinho(itens.stream().map(this::itemDe).toList());
89	    }
90	
91	    private ItemPedido itemDe(ItemInformado item) {
92	        exigir(item != null, ErroCheckout.PEDIDO_INVALIDO);
93	        exigir(positivo(item.precoUnitario()), ErroCheckout.PEDIDO_INVALIDO);
94	        exigir(item.quantidade() != null && item.quantidade() > 0, ErroCheckout.PEDIDO_INVALIDO);
95	        exigir(positivo(item.pesoKg()), ErroCheckout.PEDIDO_INVALIDO);
96	        return new ItemPedido(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg());
97	    }
98	
99	    private boolean positivo(BigDecimal valor) {
100	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
101	    }
102	
103	    private Cupom cupomDe(String codigo) {
104	        return Optional.ofNullable(codigo)
105	                .map(informado -> cupons.buscar(informado)
106	                        .orElseThrow(() -> recusar(ErroCheckout.CUPOM_INVALIDO)))
107	                .orElse(SemCupom.INSTANCIA);
108	    }
109	
110	    private void exigir(boolean condicao, ErroCheckout erro) {
111	        if (!condicao) {
112	            throw recusar(erro);
113	        }
114	    }
115	
116	    private ErroCheckoutException recusar(ErroCheckout erro) {
117	        return new ErroCheckoutException(erro);
118	    }
119	}
