1	package com.loja.checkout.dominio.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	import org.springframework.stereotype.Component;
5	
6	import java.math.BigDecimal;
7	import java.math.MathContext;
8	
9	/** Até 3x sem juros; de 4x a 12x com juros de 1,99% ao mês pela tabela Price. */
10	@Component
11	public class Cartao implements FormaPagamento {
12	
13	    private static final int MAXIMO_PARCELAS = 12;
14	    private static final int MAXIMO_SEM_JUROS = 3;
15	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
16	    private static final MathContext PRECISAO = MathContext.DECIMAL128;
17	
18	    @Override
19	    public String codigo() {
20	        return "CARTAO";
21	    }
22	
23	    @Override
24	    public boolean parcelasPermitidas(int parcelas) {
25	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
26	    }
27	
28	    @Override
29	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
30	        if (parcelas <= MAXIMO_SEM_JUROS) {
31	            return semJuros(totalPedido, parcelas);
32	        }
33	        return comJuros(totalPedido, parcelas);
34	    }
35	
36	    /** O valor final é o próprio total do pedido; a parcela é o total dividido. */
37	    private ResultadoPagamento semJuros(BigDecimal totalPedido, int parcelas) {
38	        BigDecimal parcela = Dinheiro.arredonda(totalPedido.divide(BigDecimal.valueOf(parcelas), PRECISAO));
39	        return new ResultadoPagamento(Dinheiro.arredonda(totalPedido), parcela);
40	    }
41	
42	    /** Tabela Price: parcela = total x taxa / (1 - (1 + taxa)^-parcelas). */
43	    private ResultadoPagamento comJuros(BigDecimal totalPedido, int parcelas) {
44	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, PRECISAO);
45	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, PRECISAO));
46	        BigDecimal parcela = Dinheiro.arredonda(totalPedido.multiply(TAXA_MENSAL).divide(divisor, PRECISAO));
47	        return new ResultadoPagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
48	    }
49	}
50

